program expense_review
uses expenses.pending, expenses.get, directory.lookup, llm, payroll.reimburse, mail.send
budget usd 0.50

type Classification = "business" | "personal" | "unclear"
type Row = { expense_id: Str, status: Str }

fn main() -> List[Row] max 20 {
  let ids = expenses.pending()
  return for id in ids {
    review(id)
  }
}

fn review(id: Str) -> Row {
  let e = expenses.get(id)
  let who = directory.lookup(e.employee_email)
  let category = llm.ask(Classification, "Classify this expense note as business, personal, or unclear: {e.note}", context: e.note) retry 1

  if e.currency != "EUR" {
    mail.send(to: who.manager_email, subject: "Expense {id} needs review", body: "")
    return { expense_id: id, status: "needs review" }
  }

  if category == "unclear" {
    mail.send(to: who.manager_email, subject: "Expense {id} needs review", body: "")
    return { expense_id: id, status: "needs review" }
  }

  if category == "personal" {
    mail.send(to: who.email, subject: "Expense {id} rejected", body: "")
    return { expense_id: id, status: "rejected" }
  }

  if e.amount > who.reimbursement_limit {
    mail.send(to: who.manager_email, subject: "Expense {id} needs review", body: "")
    return { expense_id: id, status: "needs review" }
  }

  payroll.reimburse(employee_id: who.id, amount: e.amount, expense_id: id)
  return { expense_id: id, status: "reimbursed" }
}

program expense_reimbursement
uses expenses.pending, expenses.get, directory.lookup, payroll.reimburse, mail.send, llm
budget usd 0.50

type Classification = { category: "business" | "personal" | "unclear" }
type Result = { expense_id: Str, status: Str }

fn main() -> List[Result] max 20 {
  let ids = expenses.pending()
  return for id in ids {
    process_expense(id)
  }
}

fn process_expense(id: Str) -> Result {
  let expense = expenses.get(id)
  let employee = directory.lookup(expense.employee_email)
  let classification = llm.ask(Classification, "Classify this expense note as business, personal, or unclear. Return only one of those three words.", context: expense.note) retry 1

  if expense.currency != "EUR" {
    mail.send(to: employee.manager_email, subject: "Expense {id} needs review", body: "")
    return { expense_id: id, status: "needs review" }
  }

  if classification.category == "unclear" {
    mail.send(to: employee.manager_email, subject: "Expense {id} needs review", body: "")
    return { expense_id: id, status: "needs review" }
  }

  if classification.category == "personal" {
    mail.send(to: employee.email, subject: "Expense {id} rejected", body: "")
    return { expense_id: id, status: "rejected" }
  }

  if expense.amount > employee.reimbursement_limit {
    mail.send(to: employee.manager_email, subject: "Expense {id} needs review", body: "")
    return { expense_id: id, status: "needs review" }
  }

  payroll.reimburse(employee_id: employee.id, amount: expense.amount, expense_id: id)
  return { expense_id: id, status: "reimbursed" }
}

program expense_review
uses expenses.pending, expenses.get, directory.lookup, llm, payroll.reimburse, mail.send
budget usd 0.50

type Verdict = "business" | "personal" | "unclear"
type Result = { expense_id: Str, status: Str }

fn main() -> List[Result] max 20 {
  let ids = expenses.pending()
  return for id in ids {
    process_expense(id)
  }
}

fn process_expense(expense_id: Str) -> Result {
  let expense = expenses.get(expense_id)
  let employee = directory.lookup(expense.employee_email)

  let verdict = llm.ask(Verdict, "Classify this expense note as business, personal, or unclear", context: expense.note)

  if expense.currency != "EUR" {
    mail.send(to: employee.manager_email, subject: "Expense {expense_id} needs review", body: "")
    return { expense_id: expense_id, status: "needs review" }
  }

  if verdict == "unclear" {
    mail.send(to: employee.manager_email, subject: "Expense {expense_id} needs review", body: "")
    return { expense_id: expense_id, status: "needs review" }
  }

  if verdict == "personal" {
    mail.send(to: employee.email, subject: "Expense {expense_id} rejected", body: "")
    return { expense_id: expense_id, status: "rejected" }
  }

  if expense.amount > employee.reimbursement_limit {
    mail.send(to: employee.manager_email, subject: "Expense {expense_id} needs review", body: "")
    return { expense_id: expense_id, status: "needs review" }
  }

  payroll.reimburse(employee_id: employee.id, amount: expense.amount, expense_id: expense_id)
  return { expense_id: expense_id, status: "reimbursed" }
}
